-- AI Interview Analyzer - PostgreSQL schema + seed data
-- GENERATED by `python -m backend.app.db.export_sql`. Do not edit by hand.
-- Usage: pgAdmin > interview_ai database > Query Tool > open this file > Run (F5).
-- Easier alternative: `python -m backend.app.db.setup` (does the same automatically).

BEGIN;

CREATE TABLE alembic_version (
    version_num VARCHAR(32) NOT NULL, 
    CONSTRAINT alembic_version_pkc PRIMARY KEY (version_num)
);

-- Running upgrade  -> 0001_initial

CREATE TABLE job_roles (
    id SERIAL NOT NULL, 
    title VARCHAR(120) NOT NULL, 
    description TEXT DEFAULT '' NOT NULL, 
    required_skills JSONB NOT NULL, 
    created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    PRIMARY KEY (id), 
    UNIQUE (title)
);

CREATE TABLE questions (
    id SERIAL NOT NULL, 
    role_id INTEGER NOT NULL, 
    order_index INTEGER DEFAULT '0' NOT NULL, 
    text TEXT NOT NULL, 
    ideal_answer TEXT DEFAULT '' NOT NULL, 
    keywords JSONB NOT NULL, 
    category VARCHAR(40) DEFAULT 'technical' NOT NULL, 
    time_limit_sec INTEGER DEFAULT '120' NOT NULL, 
    PRIMARY KEY (id), 
    FOREIGN KEY(role_id) REFERENCES job_roles (id) ON DELETE CASCADE
);

CREATE INDEX ix_questions_role_id ON questions (role_id);

CREATE TABLE candidates (
    id SERIAL NOT NULL, 
    name VARCHAR(120) NOT NULL, 
    email VARCHAR(200) NOT NULL, 
    batch VARCHAR(60), 
    resume_path VARCHAR(500), 
    resume_analysis JSONB, 
    created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    PRIMARY KEY (id)
);

CREATE UNIQUE INDEX ix_candidates_email ON candidates (email);

CREATE TABLE interviews (
    id SERIAL NOT NULL, 
    candidate_id INTEGER NOT NULL, 
    role_id INTEGER NOT NULL, 
    status VARCHAR(20) DEFAULT 'in_progress' NOT NULL, 
    overall_score FLOAT, 
    verdict VARCHAR(40), 
    summary JSONB, 
    report_pdf_path VARCHAR(500), 
    started_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    finished_at TIMESTAMP WITH TIME ZONE, 
    PRIMARY KEY (id), 
    FOREIGN KEY(candidate_id) REFERENCES candidates (id) ON DELETE CASCADE, 
    FOREIGN KEY(role_id) REFERENCES job_roles (id)
);

CREATE INDEX ix_interviews_status ON interviews (status);

CREATE INDEX ix_interviews_candidate_id ON interviews (candidate_id);

CREATE TABLE answers (
    id SERIAL NOT NULL, 
    interview_id INTEGER NOT NULL, 
    question_id INTEGER, 
    question_text TEXT NOT NULL, 
    media_path VARCHAR(500) NOT NULL, 
    status VARCHAR(20) DEFAULT 'queued' NOT NULL, 
    error TEXT, 
    transcript TEXT, 
    duration_sec FLOAT, 
    created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    processed_at TIMESTAMP WITH TIME ZONE, 
    PRIMARY KEY (id), 
    FOREIGN KEY(interview_id) REFERENCES interviews (id) ON DELETE CASCADE, 
    FOREIGN KEY(question_id) REFERENCES questions (id)
);

CREATE INDEX ix_answers_status ON answers (status);

CREATE INDEX ix_answers_interview_id ON answers (interview_id);

CREATE TABLE answer_metrics (
    id SERIAL NOT NULL, 
    answer_id INTEGER NOT NULL, 
    content_score FLOAT DEFAULT '0' NOT NULL, 
    communication_score FLOAT DEFAULT '0' NOT NULL, 
    voice_score FLOAT DEFAULT '0' NOT NULL, 
    body_language_score FLOAT DEFAULT '0' NOT NULL, 
    overall_score FLOAT DEFAULT '0' NOT NULL, 
    words_per_minute FLOAT, 
    filler_count INTEGER, 
    long_pause_count INTEGER, 
    eye_contact_pct FLOAT, 
    smile_pct FLOAT, 
    relevance_score FLOAT, 
    voice_emotion VARCHAR(30), 
    dominant_face_emotion VARCHAR(30), 
    speech JSONB NOT NULL, 
    audio JSONB NOT NULL, 
    vision JSONB NOT NULL, 
    nlp JSONB NOT NULL, 
    suggestions JSONB NOT NULL, 
    PRIMARY KEY (id), 
    UNIQUE (answer_id), 
    FOREIGN KEY(answer_id) REFERENCES answers (id) ON DELETE CASCADE
);

INSERT INTO alembic_version (version_num) VALUES ('0001_initial') RETURNING alembic_version.version_num;

COMMIT;


