INSERT INTO job_roles (title, description, required_skills) VALUES ('Software Developer', 'Build and maintain backend services and web applications using Python/Java, REST APIs, databases, Git and cloud deployment.', '["python", "java", "sql", "git", "rest api", "data structures", "algorithms", "docker", "oop", "testing"]'::jsonb);
INSERT INTO questions (role_id, order_index, text, ideal_answer, keywords, category, time_limit_sec) VALUES ((SELECT id FROM job_roles WHERE title = 'Software Developer'), 0, 'Tell me about yourself and why you are interested in this role.', 'A concise professional summary covering education, key skills, one or two relevant projects or work experiences with measurable impact, and a clear link between the candidate''s goals and the responsibilities of this role and company.', '["experience", "project", "skills", "goal", "role", "team"]'::jsonb, 'hr', 90);
INSERT INTO questions (role_id, order_index, text, ideal_answer, keywords, category, time_limit_sec) VALUES ((SELECT id FROM job_roles WHERE title = 'Software Developer'), 1, 'Explain the difference between a process and a thread.', 'A process is an independent program in execution with its own memory space, while a thread is a lightweight unit of execution inside a process that shares the process memory. Threads are cheaper to create and switch, and communicate through shared memory, but need synchronization like locks to avoid race conditions. Processes are isolated, so a crash in one does not affect others, and they communicate through inter-process communication.', '["memory", "shared", "independent", "lightweight", "context switch", "synchronization", "race condition", "isolation"]'::jsonb, 'technical', 120);
INSERT INTO questions (role_id, order_index, text, ideal_answer, keywords, category, time_limit_sec) VALUES ((SELECT id FROM job_roles WHERE title = 'Software Developer'), 2, 'What is a REST API and what makes an API RESTful?', 'REST is an architectural style where resources are identified by URLs and manipulated with standard HTTP methods like GET, POST, PUT and DELETE. A RESTful API is stateless, uses a client-server model, returns representations such as JSON, uses proper status codes, and supports caching and a uniform interface.', '["resource", "http", "get", "post", "stateless", "json", "status code", "client server"]'::jsonb, 'technical', 120);
INSERT INTO questions (role_id, order_index, text, ideal_answer, keywords, category, time_limit_sec) VALUES ((SELECT id FROM job_roles WHERE title = 'Software Developer'), 3, 'How would you find and fix a slow database query in production?', 'First measure using slow query logs or APM to find the query, then run EXPLAIN ANALYZE to inspect the execution plan. Look for full table scans and add suitable indexes, avoid SELECT *, fix N+1 queries, paginate results and consider caching. Test the change on staging, deploy, and monitor the latency afterwards.', '["explain", "index", "execution plan", "n+1", "cache", "monitor", "full table scan", "logs"]'::jsonb, 'technical', 120);
INSERT INTO questions (role_id, order_index, text, ideal_answer, keywords, category, time_limit_sec) VALUES ((SELECT id FROM job_roles WHERE title = 'Software Developer'), 4, 'Describe a challenging situation at work or college and how you handled it.', 'Using the STAR method: describe the Situation and the Task, the specific Actions the candidate personally took, and the Result with measurable outcome, followed by what they learned and would do differently.', '["situation", "task", "action", "result", "learned", "team", "deadline"]'::jsonb, 'behavioral', 120);
