INSERT INTO questions (role_id, order_index, text, ideal_answer, keywords, category, time_limit_sec) VALUES ((SELECT id FROM job_roles WHERE title = 'Data Analyst'), 1, 'How do you handle missing values in a dataset?', 'First understand why data is missing and how much is missing per column. Then choose a strategy: drop rows or columns when the missing share is small or the column is not useful, impute with mean, median or mode, use forward fill for time series, or model-based imputation. Optionally add an indicator flag and always validate the impact on the analysis.', '["drop", "impute", "mean", "median", "mode", "forward fill", "percentage", "bias"]'::jsonb, 'technical', 120);
INSERT INTO questions (role_id, order_index, text, ideal_answer, keywords, category, time_limit_sec) VALUES ((SELECT id FROM job_roles WHERE title = 'Data Analyst'), 2, 'Explain the difference between INNER JOIN, LEFT JOIN and FULL OUTER JOIN.', 'An INNER JOIN returns only rows with matching keys in both tables. A LEFT JOIN returns all rows from the left table and matching rows from the right table, with NULLs where there is no match. A FULL OUTER JOIN returns all rows from both tables, filling NULLs on whichever side has no match.', '["matching", "both tables", "left table", "null", "all rows", "key"]'::jsonb, 'technical', 120);
INSERT INTO questions (role_id, order_index, text, ideal_answer, keywords, category, time_limit_sec) VALUES ((SELECT id FROM job_roles WHERE title = 'Data Analyst'), 3, 'Tell me how you would present a data insight to a non-technical manager.', 'Start with the business question and the key takeaway, use one simple, clean visual, avoid jargon, quantify the impact in business terms like revenue or cost, give a clear recommendation and next steps, and be ready with supporting detail if asked.', '["business", "visual", "simple", "impact", "recommendation", "story", "jargon"]'::jsonb, 'technical', 120);
