INSERT INTO questions (role_id, order_index, text, ideal_answer, keywords, category, time_limit_sec) VALUES ((SELECT id FROM job_roles WHERE title = 'IT Executive'), 1, 'Explain how you would handle a sudden network outage affecting multiple departments.', 'Identify the scope and root cause by checking monitoring, switches, routers, firewall and server logs. Communicate the outage and expected timelines to the affected departments, apply a workaround or failover to restore service quickly, fix the root cause, then document the incident and preventive measures in a post-incident review.', '["root cause", "logs", "switch", "communicate", "failover", "document", "monitoring", "escalate"]'::jsonb, 'technical', 120);
INSERT INTO questions (role_id, order_index, text, ideal_answer, keywords, category, time_limit_sec) VALUES ((SELECT id FROM job_roles WHERE title = 'IT Executive'), 2, 'How do you ensure company data is backed up and recoverable?', 'Follow the 3-2-1 rule: three copies of data, on two different media, one offsite or in the cloud. Automate scheduled full and incremental backups, encrypt them, monitor backup jobs, and regularly test restores against defined RPO and RTO targets.', '["3-2-1", "offsite", "cloud", "incremental", "encrypt", "test restore", "rpo", "rto", "schedule"]'::jsonb, 'technical', 120);
