INSERT INTO questions (role_id, order_index, text, ideal_answer, keywords, category, time_limit_sec) VALUES ((SELECT id FROM job_roles WHERE title = 'Machine Learning Engineer'), 1, 'What is overfitting and how do you prevent it?', 'Overfitting is when a model learns noise in the training data and performs well on training but poorly on unseen data. Detect it with a validation set or cross-validation. Prevent it with more data, data augmentation, regularization such as L1, L2 or dropout, simpler models, early stopping and feature selection.', '["training", "validation", "generalize", "cross validation", "regularization", "dropout", "early stopping", "more data"]'::jsonb, 'technical', 120);
INSERT INTO questions (role_id, order_index, text, ideal_answer, keywords, category, time_limit_sec) VALUES ((SELECT id FROM job_roles WHERE title = 'Machine Learning Engineer'), 2, 'How would you deploy and monitor a machine learning model in production?', 'Package the model with its preprocessing into a versioned artifact, serve it behind an API such as FastAPI in a Docker container, and deploy with CI/CD. Monitor latency, errors, input data drift and prediction drift, log predictions, and retrain or roll back based on alerts.', '["api", "docker", "version", "ci/cd", "monitor", "drift", "latency", "retrain", "rollback"]'::jsonb, 'technical', 120);
